// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        vm.assume(ts > block.number + 1); // ensure block.number < ts so the mutant's stored lock is strictly below ts
        vm.deal(actor, 20 ether);

        vm.warp(ts);
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        uint256 pastAfterFirst = c.pastBlockTime();

        vm.roll(block.number + 1); // new block, same timestamp ts
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // General rule: a second valid call at the SAME timestamp ts must revert,
        // because the lock stored is block.timestamp == ts and require uses strict >.
        assertTrue(!ok2 && pastAfterFirst == ts);
    }
}
